/** A writer waiting for adjacency write admission releases the store lock, so other publications can run meanwhile. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
@Timeout(value = 2, unit = TimeUnit.MINUTES)
class LmdbAdjacencyWriteAdmissionTest {

	private static final ValueFactory F = SimpleValueFactory.getInstance();
	private static final IRI S = F.createIRI("http://example.org/admission/s");
	private static final IRI P = F.createIRI("http://example.org/admission/p");

	@TempDir
	File dataDir;

	private String previousSynchronousMaintenance;
	private SailRepository repo;

	@AfterEach
	void tearDown() {
		try {
			if (repo != null) {
				repo.shutDown();
			}
		} finally {
			if (previousSynchronousMaintenance == null) {
				System.clearProperty(LmdbDirectAdjacencyOptions.SYNCHRONOUS_MAINTENANCE_PROPERTY);
			} else {
				System.setProperty(LmdbDirectAdjacencyOptions.SYNCHRONOUS_MAINTENANCE_PROPERTY,
						previousSynchronousMaintenance);
			}
		}
	}

	private static String threadDump() {
		StringBuilder dump = new StringBuilder();
		Thread.getAllStackTraces().forEach((thread, stack) -> {
			if (thread.getName().startsWith("admission-") || thread.getName().contains("adjacency")) {
				dump.append(thread.getName()).append(' ').append(thread.getState()).append('\n');
				for (int i = 0; i < Math.min(stack.length, 40); i++) {
					dump.append("    at ").append(stack[i]).append('\n');
				}
			}
		});
		return dump.toString();
	}

	@Test
	void aWriterThatWaitedForAdmissionSurvivesAnotherConnectionsRollback() throws Exception {
		previousSynchronousMaintenance = System
				.getProperty(LmdbDirectAdjacencyOptions.SYNCHRONOUS_MAINTENANCE_PROPERTY);
		// Commit deltas go through the apply queue, so a paused applier leaves a backlog above the 1-byte limit.
		System.setProperty(LmdbDirectAdjacencyOptions.SYNCHRONOUS_MAINTENANCE_PROPERTY, "false");
		LmdbStore sail = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc").setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30)
				.setDirectAdjacencyBacklogMaxBytes(1L));
		repo = new SailRepository(sail);
		repo.init();
		Set<Statement> expected = new HashSet<>();
		try (RepositoryConnection connection = repo.getConnection()) {
			Statement first = F.createStatement(S, P, F.createIRI("http://example.org/admission/o0"));
			connection.add(first);
			expected.add(first);
		}
		assertThat(sail.awaitDirectAdjacencyReady(30, TimeUnit.SECONDS)).isTrue();
		LmdbDirectAdjacencyStore direct = sail.getBackingStore().directAdjacencyStore();
		direct.pauseApplierForTest(true);
		try (RepositoryConnection connection = repo.getConnection()) {
			Statement queued = F.createStatement(S, P, F.createIRI("http://example.org/admission/o1"));
			connection.add(queued);
			expected.add(queued);
		}

		AtomicBoolean first = new AtomicBoolean(true);
		AtomicReference<Throwable> otherFailure = new AtomicReference<>();
		direct.beforeWriteAdmissionWaitForTest = () -> {
			if (!first.compareAndSet(true, false)) {
				return;
			}
			// While this writer waits without the store lock, the other connection rolls back. Then the backlog
			// drains and admits the waiting writer.
			Thread other = new Thread(() -> {
				// A NONE transaction with nothing written holds no writer lease, yet its rollback reaches the store.
				try (RepositoryConnection rollingBack = repo.getConnection()) {
					rollingBack.begin(IsolationLevels.NONE);
					rollingBack.rollback();
				} catch (Throwable failure) {
					otherFailure.set(failure);
				}
				direct.pauseApplierForTest(false);
			}, "admission-rolling-back-writer");
			other.start();
		};
		Statement waited = F.createStatement(S, P, F.createIRI("http://example.org/admission/o2"));
		AtomicReference<Throwable> waitedFailure = new AtomicReference<>();
		Thread writer = new Thread(() -> {
			try (RepositoryConnection connection = repo.getConnection()) {
				connection.begin(IsolationLevels.NONE);
				connection.add(waited);
				connection.commit();
			} catch (Throwable failure) {
				waitedFailure.set(failure);
			}
		}, "admission-waiting-writer");
		writer.start();
		writer.join(TimeUnit.SECONDS.toMillis(30));
		assertThat(writer.isAlive()).as("the waiting writer finished%n%s", threadDump()).isFalse();
		assertThat(waitedFailure.get()).isNull();
		expected.add(waited);
		assertThat(first.get()).as("the writer waited for admission").isFalse();
		assertThat(otherFailure.get()).isNull();

		try (RepositoryConnection connection = repo.getConnection()) {
			Set<Statement> actual = new HashSet<>();
			try (RepositoryResult<Statement> result = connection.getStatements(S, P, null, false)) {
				result.forEach(actual::add);
			}
			assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
		}
	}
}
